function costAmount(value){const raw=value.trim().replace(',','.');if(!/^[0-9]{1,5}(\.[0-9]{1,2})?$/.test(raw))throw Error('Informe os custos com até duas casas decimais.');const [whole,fraction='']=raw.split('.');const cents=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(cents>1000000)throw Error('Cada custo pode ter no máximo R$ 10.000,00.');return cents;}
function validProductionCostsState(value){if(!value||!Number.isSafeInteger(value.revision)||value.revision<1||!value.values||!['all_inclusive','itemized'].includes(value.values.mode))return null;const v=value.values,cent=value=>Number.isSafeInteger(value)&&value>=0&&value<=1000000;if(!cent(v.inclusive_regular_cents)||v.inclusive_regular_cents===0||!cent(v.inclusive_plus_cents)||v.inclusive_plus_cents===0||!['base_regular_cents','base_plus_cents'].every(key=>v[key]===null||(cent(v[key])&&v[key]>0))||!Array.isArray(v.components)||v.components.length>20)return null;const ids=new Set();for(const row of v.components){if(!row||typeof row.id!=='string'||!/^[a-z0-9-]{1,64}$/.test(row.id)||ids.has(row.id)||typeof row.label!=='string'||!row.label.trim()||row.label.length>60||/[\u0000-\u001f\u007f-\u009f]/.test(row.label)||!['per_piece','per_kit'].includes(row.basis)||!cent(row.amount_cents))return null;ids.add(row.id);}if(v.mode==='itemized'&&(v.base_regular_cents===null||v.base_plus_cents===null))return null;return {revision:value.revision,values:structuredClone(v),updated_at:value.updated_at};}
function productionCostsValues(){const active=el('costMode').value;const optional=id=>el(id).value.trim()===''?null:costAmount(el(id).value);const components=[...el('costComponents').children].map(row=>({id:row.dataset.componentId,label:row.querySelector('[data-cost-label]').value.trim(),basis:row.querySelector('[data-cost-basis]').value,amount_cents:costAmount(row.querySelector('[data-cost-amount]').value)}));for(const row of components)if(!row.label||row.label.length>60||/[\u0000-\u001f\u007f-\u009f]/.test(row.label))throw Error('Dê um nome de até 60 caracteres a cada componente.');const v={mode:active,inclusive_regular_cents:costAmount(el('costInclusiveRegular').value),inclusive_plus_cents:costAmount(el('costInclusivePlus').value),base_regular_cents:optional('costBaseRegular'),base_plus_cents:optional('costBasePlus'),components};if(v.inclusive_regular_cents===0||v.inclusive_plus_cents===0)throw Error('O custo completo por peça deve ser maior que zero.');if((v.base_regular_cents!==null&&v.base_regular_cents===0)||(v.base_plus_cents!==null&&v.base_plus_cents===0))throw Error('A base da camiseta deve ser maior que zero.');if(active==='itemized'&&(v.base_regular_cents===null||v.base_plus_cents===null))throw Error('Informe as duas bases da camiseta, sem os componentes separados.');return v;}
function productionCostKitValues(values){const extra=values.mode==='itemized'?values.components.reduce((sum,row)=>sum+row.amount_cents*(row.basis==='per_piece'?2:1),0):0;const regular=values.mode==='all_inclusive'?values.inclusive_regular_cents:values.base_regular_cents,plus=values.mode==='all_inclusive'?values.inclusive_plus_cents:values.base_plus_cents;return [regular*2+extra,regular+plus+extra,plus*2+extra];}
function updateProductionCostsPreview(){const mode=el('costMode').value;el('costInclusive').hidden=mode!=='all_inclusive';el('costItemized').hidden=mode!=='itemized';el('addCostComponent').disabled=el('costComponents').children.length>=20||productionCostsSaving;const target=el('costsPreview');target.replaceChildren();let valid=false;try{const values=productionCostsValues(),amounts=productionCostKitValues(values);for(const [index,label] of ['Kit com duas P–GG','Kit P–GG + G1–G3','Kit com duas G1–G3'].entries()){const card=node('div');card.append(node('small',label),node('strong',money(amounts[index])));target.append(card);}valid=true;}catch(error){target.append(node('p',productionCostsState?error.message:'Os valores aparecerão depois da consulta dos custos salvos.','field-help'));}el('costsDraftNote').textContent=productionCostsDirty?'Prévia do rascunho. Salve para aplicar aos vínculos confirmados.':'Referência da versão salva · uma camiseta masculina e uma feminina por kit.';el('saveProductionCosts').disabled=!productionCostsState||!!productionCostsPromise||productionCostsSaving||productionCostsBlocked||!!productionCostsConflict||!productionCostsDirty||!valid;el('saveProductionCosts').textContent=productionCostsSaving?'Salvando custos…':'Salvar custos de produção';el('loadProductionCosts').disabled=!!productionCostsPromise||productionCostsSaving;el('reviewProductionCosts').hidden=!productionCostsConflict;el('costsVersion').textContent=productionCostsState?'Custos · versão '+productionCostsState.revision:'Custos indisponíveis';}
