function appendCostComponent(value){const row=node('div',undefined,'cost-component');row.dataset.componentId=value?.id||crypto.randomUUID();for(const [kind,label] of [['label','Componente'],['basis','Aplicar'],['amount','Custo · R$']]){const wrap=node('div',undefined,'field'),caption=node('label',label),input=node(kind==='basis'?'select':'input');input.id='cost-component-'+row.dataset.componentId+'-'+kind;caption.htmlFor=input.id;if(kind==='basis'){input.dataset.costBasis='true';for(const [optionValue,text] of [['per_piece','Por peça'],['per_kit','Por kit']]){const option=node('option',text);option.value=optionValue;input.append(option);}input.value=value?.basis||'per_piece';}else if(kind==='label'){input.dataset.costLabel='true';input.maxLength=60;input.placeholder='Ex.: estampa';input.value=value?.label||'';}else{input.dataset.costAmount='true';input.inputMode='decimal';input.placeholder='0,00';input.value=value?String((value.amount_cents/100).toFixed(2)):'';}input.addEventListener(kind==='basis'?'change':'input',productionCostsChanged);wrap.append(caption,input);row.append(wrap);}const remove=node('button','Remover','button-secondary');remove.type='button';remove.setAttribute('aria-label','Remover componente');remove.onclick=()=>{row.remove();productionCostsChanged();};row.append(remove);el('costComponents').append(row);}
function applyProductionCosts(value){productionCostsState=value;const v=value.values;el('costMode').value=v.mode;for(const [id,key] of [['costInclusiveRegular','inclusive_regular_cents'],['costInclusivePlus','inclusive_plus_cents'],['costBaseRegular','base_regular_cents'],['costBasePlus','base_plus_cents']])el(id).value=v[key]===null?'':(v[key]/100).toFixed(2);el('costComponents').replaceChildren();for(const component of v.components)appendCostComponent(component);productionCostsDirty=false;productionCostsBlocked=false;productionCostsConflict=null;el('costsNotice').hidden=true;el('costsStatus').textContent='Custos cadastrados · versões anteriores preservadas.';updateProductionCostsPreview();}
async function loadProductionCostsAudit(){try{const value=await api('production-costs/audit'),target=el('productionCostsAudit');if(!value||!Array.isArray(value.rows))throw Error();target.replaceChildren();for(const row of value.rows.slice(0,30)){const entry=validProductionCostsState({revision:row.revision,values:JSON.parse(row.payload),updated_at:row.created_at});if(!entry)throw Error();const kits=productionCostKitValues(entry.values);target.append(node('p','Versão '+entry.revision+' · '+new Date(row.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})+' · '+(entry.values.mode==='all_inclusive'?'custo completo':'custos separados')+' · kits '+kits.map(value=>money(value)).join(' / ')));}if(!value.rows.length)target.append(node('p','Nenhuma versão anterior disponível.','muted'));}catch{el('productionCostsAudit').replaceChildren(node('p','Não foi possível consultar o histórico dos custos. Carregue os custos salvos para tentar novamente.','muted'));}}
async function loadProductionCosts(){if(productionCostsPromise)return productionCostsPromise;el('costsStatus').textContent='Consultando os custos salvos…';productionCostsPromise=(async()=>{try{const value=validProductionCostsState(await api('production-costs'));if(!value)throw Error('A resposta dos custos não pôde ser validada.');if(productionCostsDirty){productionCostsConflict=value;productionCostsBlocked=true;el('costsNotice').hidden=false;el('costsNotice').replaceChildren(node('p','Custos atuais carregados. Seus rascunhos foram preservados; revise a versão atual antes de salvar.'),node('p','Versão '+value.revision+' salva: '+(value.values.mode==='all_inclusive'?'custo completo':'custos separados')+' · custo completo P–GG '+money(value.values.inclusive_regular_cents)+' / G1–G3 '+money(value.values.inclusive_plus_cents)+'.'),node('p','Kits da versão salva: '+productionCostKitValues(value.values).map(amount=>money(amount)).join(' / ')+'. Seu rascunho completo substituirá esses valores ao salvar.'));el('costsStatus').textContent='Versão salva '+value.revision+' disponível para revisão.';}else applyProductionCosts(value);await loadProductionCostsAudit();}catch(error){productionCostsBlocked=true;el('costsNotice').hidden=false;el('costsNotice').textContent=error.message;el('costsStatus').textContent='Não foi possível carregar os custos. Os rascunhos foram preservados.';}finally{productionCostsPromise=null;updateProductionCostsPreview();}})();updateProductionCostsPreview();return productionCostsPromise;}
async function saveProductionCosts(){if(el('saveProductionCosts').disabled||productionCostsSaving||!productionCostsState||productionCostsBlocked)return;let values;try{values=productionCostsValues();}catch(error){notice(error.message);return;}const submittedSequence=productionCostsEditSequence;productionCostsSaving=true;updateProductionCostsPreview();try{const value=validProductionCostsState(await api('production-costs',{revision:productionCostsState.revision,values}));if(!value)throw Error('Não foi possível validar os custos salvos. Carregue os custos atuais antes de continuar.');if(submittedSequence===productionCostsEditSequence)applyProductionCosts(value);else{productionCostsState=value;el('costsStatus').textContent='Custos salvos. Os novos rascunhos continuam no formulário.';}notice('Custos de produção salvos. As margens já cadastradas permanecem separadas.');await loadProductionCostsAudit();await loadVariants();}catch(error){productionCostsBlocked=true;el('costsNotice').hidden=false;el('costsNotice').textContent=error.status===409?'Os custos foram alterados em outra sessão. Seus rascunhos foram preservados. Use Carregar custos salvos e revise a versão atual antes de salvar.':error.message;el('costsStatus').textContent='A edição aguarda a consulta e a revisão dos custos salvos.';}finally{productionCostsSaving=false;updateProductionCostsPreview();}}
function renderItemsProductionCosts(){const target=el('itemsProductionCosts'),reference=itemsData?.production_cost_reference;target.replaceChildren();target.hidden=!reference;if(!reference)return;const cent=value=>Number.isSafeInteger(value)&&value>=0;if(reference.currency!=='BRL'||reference.cost_stage!=='PRODUCTION_COST_REFERENCE'||reference.status_scope!=='ALL_RETURNED_STATUSES_REFERENCE_ONLY'||!cent(reference.known_subset_cents)||(reference.total_cents!==null&&!cent(reference.total_cents))||!cent(reference.mapped_quantity)||!cent(reference.unmapped_quantity)){target.append(node('p','A referência dos custos de produção não pôde ser validada.'));return;}target.append(node('h3','Custo de produção dos kits · referência'),node('p','Parte com vínculo salvo: '+money(reference.known_subset_cents)+'.'),node('p',reference.total_cents===null?'Custo completo pendente: há unidades sem composição confirmada.':'Custo de produção do recorte: '+money(reference.total_cents)+'.'),node('p',reference.mapped_quantity+' unidade(s) vinculada(s) · '+reference.unmapped_quantity+' sem vínculo.'),node('p','Inclui todos os status retornados. É uma referência de produção para as quantidades do catálogo; não confirma custo realizado, recebimento ou venda paga.'),node('p','Lucro bruto aguarda receita e dados financeiros da venda.'),node('p','Os custos não são descontados novamente das margens já cadastradas.','field-help'),node('p','O perfil atual é aplicado a esta leitura. Os recortes salvos preservam as margens anteriores e ainda não incluem estes custos de produção.','field-help'));if(Number.isSafeInteger(reference.costs_revision)&&Number.isSafeInteger(reference.bindings_revision))target.append(node('p','Custos · versão '+reference.costs_revision+' / vínculos · versão '+reference.bindings_revision,'field-help'));}
function variantCostReference(key){const references=itemsData?.production_cost_reference?.variants,row=Array.isArray(references)?references.find(value=>variantKey(value)===key):null;if(bindingDrafts.has(key))return 'O custo de produção será associado depois de salvar a composição.';return row&&Number.isSafeInteger(row.unit_cost_cents)&&row.unit_cost_cents>=0?'Custo de produção por kit: '+money(row.unit_cost_cents)+' · referência cadastrada.':'Custo de produção pendente: confirme a composição desta variação.';}

function observationDate(value){const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Horário não informado';}
function observationAmount(value){return Number.isSafeInteger(value)&&value>=0;}
function validObservationRow(row){return row&&typeof row==='object'&&!Array.isArray(row)&&typeof row.id==='string'&&/^[a-f0-9]{64}$/.test(row.id)&&typeof row.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(row.date)&&Number.isFinite(Date.parse(row.through_at))&&Number.isFinite(Date.parse(row.saved_at))&&['catalog_units','orders_in_api_window','mapped_quantity','unmapped_quantity','known_subset_cents'].every(key=>observationAmount(row[key]))&&(row.total_cents===null||observationAmount(row.total_cents))&&['settings_revision','bindings_revision'].every(key=>Number.isSafeInteger(row[key])&&row[key]>0);}
function validObservationDetail(value){if(!value||typeof value!=='object'||value.schema!=='order_observation_v1'||value.coverage!=='PARTIAL_DAY_SNAPSHOT'||value.ads_execution!=='LOCKED'||value.economic_status!=='UNKNOWN'||value.hermes_context!=='NOT_ATTACHED'||typeof value.id!=='string'||!/^[a-f0-9]{64}$/.test(value.id)||!Number.isFinite(Date.parse(value.saved_at)))return null;const source=value.source_snapshot,settings=value.settings_snapshot,bindings=validBindingState(value.bindings_snapshot),reference=value.margin_reference;if(!source||!/^\d{4}-\d{2}-\d{2}$/.test(source.date)||!Number.isFinite(Date.parse(source.through_at))||!observationAmount(source.catalog_units)||!observationAmount(source.orders_in_api_window)||!groupVariantRows(source.rows)||!settings||!Number.isSafeInteger(settings.revision)||settings.revision<1||!settings.values||!['regular_cents','mixed_cents','plus_cents','ad_share_percent'].every(key=>observationAmount(settings.values[key]))||!bindings||!reference||!Array.isArray(reference.variants)||!['mapped_quantity','unmapped_quantity','known_subset_cents'].every(key=>observationAmount(reference[key]))||(reference.total_cents!==null&&!observationAmount(reference.total_cents)))return null;return value;}
function updateObservationCaptureState(){const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo'}).format(new Date());el('saveObservation').disabled=observationSaving||!!itemsPromise||bindingSaving||!itemsData||itemsData.date!==today;el('saveObservation').textContent=observationSaving?'Guardando recorte…':'Guardar recorte atual';}
function renderObservations(){const target=el('observationsList');target.replaceChildren();for(const row of observationRows){const button=node('button',undefined,'observation-entry');button.type='button';button.dataset.observationId=row.id;button.setAttribute('aria-pressed',String(row.id===selectedObservationId));button.append(node('strong',row.date.split('-').reverse().join('/')+' · parcial'),node('span','Até '+observationDate(row.through_at)+' · Brasília'),node('span',row.catalog_units+' unidade(s) · '+row.orders_in_api_window+' pedido(s) na janela'),node('span','Guardado em '+observationDate(row.saved_at)+' · Brasília'),node('span','Margens v'+row.settings_revision+' / vínculos v'+row.bindings_revision));button.onclick=()=>selectObservation(row.id);target.append(button);}if(!observationRows.length)target.append(node('p','Nenhum recorte salvo nesta lista. Guarde uma leitura para começar.','muted'));el('observationsMore').hidden=!observationsCursor;el('observationsMore').disabled=!!observationsPromise;}
function renderObservationDetail(value){const target=el('observationDetail');target.replaceChildren();const source=value.source_snapshot,reference=value.margin_reference,settings=value.settings_snapshot,bindings=new Map(value.bindings_snapshot.bindings.map(row=>[variantKey(row),row])),groups=groupVariantRows(source.rows),references=new Map(reference.variants.map(row=>[variantKey(row),row]));target.append(node('span','RECORTE PARCIAL SALVO','eyebrow'),node('h3',source.date.split('-').reverse().join('/')+' · até '+observationDate(source.through_at)),node('p','Guardado em '+observationDate(value.saved_at)+' · Brasília.','field-help'),node('p','Margens · versão '+settings.revision+' / vínculos · versão '+value.bindings_snapshot.revision,'variant-version'));const metrics=node('div',undefined,'report-metrics');for(const [label,amount,help] of [['Unidades de catálogo',source.catalog_units,'Inclui todos os status retornados'],['Pedidos na janela da API',source.orders_in_api_window,'Sem filtro de status; contador não reconciliado']]){const card=node('div',undefined,'report-metric');card.append(node('small',label),node('strong',new Intl.NumberFormat('pt-BR').format(amount)),node('span',help));metrics.append(card);}target.append(metrics);const economic=node('div',undefined,'help-box');economic.append(node('h3','Referências salvas antes dos anúncios'),node('p','Parte com vínculo salvo: '+money(reference.known_subset_cents)+'.'),node('p',reference.total_cents===null?'Referência completa pendente: há unidades sem composição confirmada.':'Referência completa do recorte: '+money(reference.total_cents)+'.'),node('p',reference.mapped_quantity+' unidade(s) vinculada(s) · '+reference.unmapped_quantity+' sem vínculo.'),node('p','Margens configuradas: regular '+money(settings.values.regular_cents)+' · mista '+money(settings.values.mixed_cents)+' · plus '+money(settings.values.plus_cents)+'. Referência Ads: '+settings.values.ad_share_percent+'%.'),node('p','Taxas e custos das peças já estão descontados dessas margens. Anúncios não foram descontados. O registro não confirma recebimento, lucro ou vendas atribuídas a anúncios.'));target.append(economic);const variants=node('div',undefined,'observation-variants');for(const [key,group] of groups){const card=node('div',undefined,'observation-variant'),binding=bindings.get(key),ref=references.get(key);card.append(node('h4','Produto #'+group.item_id+' · variação #'+group.model_id),node('p',group.quantity+' unidade(s) de catálogo · '+group.line_count+' linha(s) de itens.'));for(const [status,totals] of group.statuses)card.append(node('p',status+': '+totals.quantity+' unidade(s) · '+totals.lines+' linha(s).'));if(binding)card.append(node('p',(binding.source==='CATALOG_VARIATION_AXES'?'Kit identificado pelo catálogo: masculino ':'Kit confirmado: masculino ')+binding.male_size+' / feminino '+binding.female_size+'.'));else card.append(node('p','Composição sem vínculo salvo neste registro.'));if(ref&&observationAmount(ref.unit_margin_cents)&&observationAmount(ref.contribution_cents))card.append(node('p','Referência por unidade: '+money(ref.unit_margin_cents)+' · subtotal: '+money(ref.contribution_cents)+' antes dos anúncios.'));else card.append(node('p','Referência de margem indisponível para esta variação.'));variants.append(card);}if(!groups.size)variants.append(node('p','A fonte não retornou itens neste recorte.','muted'));target.append(node('h3','Itens observados'),variants,node('p','Recorte parcial preservado. Não representa o fechamento do dia e ainda não foi anexado às análises do Hermes. Anúncios seguem protegidos.','field-help'));}
async function selectObservation(id){const sequence=++observationSelectionSequence;selectedObservationId=id;renderObservations();el('observationDetail').replaceChildren(node('p','Carregando o recorte salvo…','muted'));try{const detail=validObservationDetail(await api('order-observations/'+id));if(!detail)throw Error('Não foi possível validar o recorte salvo.');if(sequence!==observationSelectionSequence)return;renderObservationDetail(detail);el('observationDetail').scrollIntoView({block:'start'});}catch(error){if(sequence===observationSelectionSequence)el('observationDetail').replaceChildren(node('p',error.message,'muted'));}}
